def hold_grip(arm, grip, count):
    obs = get_observation()
    state = obs['state']
    action = {'left_ee_pose':state['left_ee_pose'], 'right_ee_pose':state['right_ee_pose'], 'left_ee_joint_state':state['left_ee_joint_state'], 'right_ee_joint_state':state['right_ee_joint_state']}
    action[arm + '_ee_joint_state'] = [grip]
    for i in range(count):
        obs, reward, terminated, truncated, info = step(action)
        if terminated or truncated:
            return 'ended'
    return 'held'
