# The carried bowl is low over the empty central table region.
# Release it, clear vertically, and return the right arm home before left-arm work.
def home_arm(arm, count=30):
    state = get_observation()['state']
    action = {k: list(v) for k,v in state.items() if k.endswith('joint_state')}
    action[arm + '_arm_joint_state'] = home[arm + '_arm_joint_state']
    action[arm + '_ee_joint_state'] = [1.0]
    for i in range(count):
        obs, reward, terminated, truncated, info = step(action)
        if terminated or truncated:
            print('ended', info)
            return 'ended'
    print('home',arm,obs['state'][arm + '_arm_joint_state'])
    return 'held'
